import{_ as p,K as t,a as s,c as o,ac as a,b as n,q as i}from"./chunks/framework.BSuaGltH.js";const x=JSON.parse('{"title":"小学一年级数学：知识讲解","description":"小学一年级数学 18 个知识点，包含定义、方法、例题、易错与本地图示。","frontmatter":{"title":"小学一年级数学：知识讲解","description":"小学一年级数学 18 个知识点，包含定义、方法、例题、易错与本地图示。","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"知识讲解","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学 · 一年级","summary":"小学一年级数学 18 个知识点，包含定义、方法、例题、易错与本地图示。","status":"active","related":[{"title":"八年级数学独立习题集","link":"/life/math/junior/grade-8/exercises","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 平方根、立方根与实数至一次函数与实际方案比较","link":"/life/math/junior/grade-8/exercises-part-01","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 三角形全等与对应关系至加权平均数与方差","link":"/life/math/junior/grade-8/exercises-part-02","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"程序员数学 11：文件处理任务的数学复盘","link":"/life/math/programmer/practice","kind":"习题与解析","scope":"general","audience":"general"}],"prev":false,"next":{"text":"小学一年级数学：公式与规则速查","link":"/life/math/primary/grade-1/formulas"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"小学一年级数学：公式与规则速查","link":"/life/math/primary/grade-1/formulas"}},"headers":[],"relativePath":"life/math/primary/grade-1/knowledge.md","filePath":"life/math/primary/grade-1/knowledge.md"}'),g={name:"life/math/primary/grade-1/knowledge.md"};function l(h,r,m,d,f,c){const e=t("ArticleImage");return s(),o("div",null,[r[0]||(r[0]=a('<h1 id="小学一年级数学-知识讲解" tabindex="-1">小学一年级数学：知识讲解 <a class="header-anchor" href="#小学一年级数学-知识讲解" aria-label="Permalink to &quot;小学一年级数学：知识讲解&quot;">​</a></h1><p><a href="/life/math/primary/grade-1/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-1/formulas">公式速查</a> · <a href="/life/math/primary/grade-1/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><p>重点是用实物、计数与短句理解数量关系，再过渡到算式；家长或教师可协助读题，但先让学生独立说出理由。</p><p>本年级共有 <strong>18 个知识点</strong>，配套 <strong>36 道练习</strong>；每个编号均可在公式与习题页找到对应内容。建议先读定义，自己解释例子，再独立练习，最后展开答案核对。</p><h2 id="p1-01" tabindex="-1">数数、基数与序数 <a class="header-anchor" href="#p1-01" aria-label="Permalink to &quot;数数、基数与序数 {#p1-01}&quot;">​</a></h2><p><strong>定义与条件：</strong> 数数要让一个物体对应一个数，最后数到的数表示总数，叫基数；“第几个”表示顺序，叫序数。0 可以表示一个也没有。</p><p><strong>方法：</strong> 先明确数的对象，再说明从哪一端开始数；求两人之间有几人时，通常不包含两端的人。</p><p><strong>例子：</strong> 一排有 8 人，小华从左数第 3，则他右边有 5 人：先去掉左边 2 人及他自己，再数余下的人。</p><p><strong>易错：</strong> “第 3 个”只指一个位置，“3 个”表示数量；改变起点会改变序数。</p><p><a href="/life/math/primary/grade-1/formulas#p1-01">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-01">练习题组</a></p><h2 id="p1-02" tabindex="-1">100 以内的数位与组成 <a class="header-anchor" href="#p1-02" aria-label="Permalink to &quot;100 以内的数位与组成 {#p1-02}&quot;">​</a></h2><p><strong>定义与条件：</strong> 从右往左依次是个位、十位、百位；10 个一是 1 个十，10 个十是 1 个百。同一个数字在不同数位表示不同数量。</p><p><strong>方法：</strong> 先数整十，再数剩余的个数；读两位数时先读十位，再读个位。用小棒捆成十能看清进位。</p><p><strong>例子：</strong> 4 捆十根小棒与 7 根散棒合起来是 47；其中 4 表示 4 个十，7 表示 7 个一。</p><p><strong>易错：</strong> 40 中的 0 表示没有剩余的一个，不能把 40 写成 4。</p><p><a href="/life/math/primary/grade-1/formulas#p1-02">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-02">练习题组</a></p><h2 id="p1-03" tabindex="-1">比较大小与数的顺序 <a class="header-anchor" href="#p1-03" aria-label="Permalink to &quot;比较大小与数的顺序 {#p1-03}&quot;">​</a></h2><p><strong>定义与条件：</strong> 比较数的大小就是比较数量多少；使用大于号、小于号、等号记录结果。100 以内的整数可按从小到大排列。</p><p><strong>方法：</strong> 位数多的非负整数较大；位数相同，从最高位开始逐位比较，遇到不同的数位即可确定大小。</p><p><strong>例子：</strong> 58 与 62 的十位分别是 5 和 6，所以 58＜62，不必再比较个位。</p><p><strong>易错：</strong> 不能只看个位：个位 9 的 39 仍小于个位 1 的 41。</p><p><a href="/life/math/primary/grade-1/formulas#p1-03">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-03">练习题组</a></p><h2 id="p1-04" tabindex="-1">10 以内加减法的意义 <a class="header-anchor" href="#p1-04" aria-label="Permalink to &quot;10 以内加减法的意义 {#p1-04}&quot;">​</a></h2><p><strong>定义与条件：</strong> 加法表示合并或增加；减法表示去掉，或由总数求剩余部分。加数、和与被减数、减数、差应与情境对应。</p><p><strong>方法：</strong> 先找原有多少、增加或减少多少，再列式；也可以用计数物或数线检查。</p><p><strong>例子：</strong> 盒中有 6 块积木，拿走 2 块，还剩 6−2＝4 块；反过来，4＋2＝6 能检查结果。</p><p><strong>易错：</strong> 题目出现“一共”不一定机械用加法，要先确认已知的是部分还是总数。</p><p><a href="/life/math/primary/grade-1/formulas#p1-04">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-04">练习题组</a></p><h2 id="p1-05" tabindex="-1">20 以内进位加法与凑十 <a class="header-anchor" href="#p1-05" aria-label="Permalink to &quot;20 以内进位加法与凑十 {#p1-05}&quot;">​</a></h2><p><strong>定义与条件：</strong> 两个一位数相加满十时，要把 10 个一组成 1 个十；凑十法利用十进制使口算更方便。</p><p><strong>方法：</strong> 看较大数离 10 还差几，把另一个加数分成相应两部分，先凑十，再加余数。</p><p><strong>例子：</strong> 8＋7：把 7 分成 2 和 5，先算 8＋2＝10，再算 10＋5＝15。</p><p><strong>易错：</strong> 拆分的两部分之和必须等于原来的加数；凑走了多少，余下就要少多少。</p><p><a href="/life/math/primary/grade-1/formulas#p1-05">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-05">练习题组</a></p><h2 id="p1-06" tabindex="-1">20 以内退位减法与想加算减 <a class="header-anchor" href="#p1-06" aria-label="Permalink to &quot;20 以内退位减法与想加算减 {#p1-06}&quot;">​</a></h2><p><strong>定义与条件：</strong> 十几减去一位数，个位不够减时，需要把 1 个十分成 10 个一，或根据加减法的联系求差。</p><p><strong>方法：</strong> 破十法先用 10 减去减数，再加原个位；想加算减则想“减数加几等于被减数”。</p><p><strong>例子：</strong> 13−8＝(10−8)＋3＝5；也可想 8＋5＝13。</p><p><strong>易错：</strong> 从十位借出的 10 必须实际拆开，不能让个位直接做 3−8。</p><p><a href="/life/math/primary/grade-1/formulas#p1-06">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-06">练习题组</a></p><h2 id="p1-07" tabindex="-1">100 以内不进位加法与不退位减法 <a class="header-anchor" href="#p1-07" aria-label="Permalink to &quot;100 以内不进位加法与不退位减法 {#p1-07}&quot;">​</a></h2><p><strong>定义与条件：</strong> 把十位和个位分别计算，再把结果合起来；相同数位表示相同的计数单位。</p><p><strong>方法：</strong> 列竖式时个位对个位、十位对十位，从个位算起；口算可以分成整十与零几。</p><p><strong>例子：</strong> 34＋25＝(30＋20)＋(4＋5)＝59；68−24＝(60−20)＋(8−4)＝44。</p><p><strong>易错：</strong> 不能把个位的 5 加到十位的 3 上。</p><p><a href="/life/math/primary/grade-1/formulas#p1-07">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-07">练习题组</a></p><h2 id="p1-08" tabindex="-1">100 以内进位加法与退位减法 <a class="header-anchor" href="#p1-08" aria-label="Permalink to &quot;100 以内进位加法与退位减法 {#p1-08}&quot;">​</a></h2><p><strong>定义与条件：</strong> 个位满十向十位进 1；个位不够减时，从十位退 1，把它换成 10 个一。进位与退位都保持总量不变。</p><p><strong>方法：</strong> 标记进位或退位，逐位运算；算完用逆运算检查，尤其检查十位是否已经变化。</p><p><strong>例子：</strong> 27＋35：7＋5＝12，写 2 进 1，十位 2＋3＋1＝6，得 62；52−28＝24。</p><p><strong>易错：</strong> 进位的 1 不能漏加；退位后原十位必须减 1。</p><p><a href="/life/math/primary/grade-1/formulas#p1-08">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-08">练习题组</a></p><h2 id="p1-09" tabindex="-1">连加、连减与加减混合 <a class="header-anchor" href="#p1-09" aria-label="Permalink to &quot;连加、连减与加减混合 {#p1-09}&quot;">​</a></h2><p><strong>定义与条件：</strong> 没有括号的连加、连减、加减混合算式，按从左到右的顺序计算；每一步都要记录当前数量。</p><p><strong>方法：</strong> 可以把情境画成“原有→变化→再变化”，每个箭头对应一个运算。</p><p><strong>例子：</strong> 公交车上有 12 人，下车 4 人，再上车 6 人：12−4＋6＝8＋6＝14。</p><p><strong>易错：</strong> 连减 15−3−2 不能算成 15−(3−2)。</p><p><a href="/life/math/primary/grade-1/formulas#p1-09">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-09">练习题组</a></p><h2 id="p1-10" tabindex="-1">求差与多几、少几问题 <a class="header-anchor" href="#p1-10" aria-label="Permalink to &quot;求差与多几、少几问题 {#p1-10}&quot;">​</a></h2><p><strong>定义与条件：</strong> 比较两个数量时，可把一样多的部分配对，剩下的就是相差量。“多几”和“少几”描述同一个差。</p><p><strong>方法：</strong> 先确定较大数、较小数及所求量。求相差用减法；知道较小数和多的数求较大数用加法。</p><p><strong>例子：</strong> 红球 15 个、蓝球 9 个，红球比蓝球多 15−9＝6 个，蓝球也比红球少 6 个。</p><p><strong>易错：</strong> 题目带“多”不代表一定用加法，要看是在求差还是求较大数。</p><p><a href="/life/math/primary/grade-1/formulas#p1-10">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-10">练习题组</a></p><h2 id="p1-11" tabindex="-1">上下、前后、左右与参照物 <a class="header-anchor" href="#p1-11" aria-label="Permalink to &quot;上下、前后、左右与参照物 {#p1-11}&quot;">​</a></h2><p><strong>定义与条件：</strong> 位置关系需要参照物。上下通常由竖直方向确定，前后和左右常与观察者的朝向有关。</p><p><strong>方法：</strong> 先说明“以谁为标准”，再描述相对位置；面对面的人左、右方向可能相反。</p><p><strong>例子：</strong> 三人面向黑板，从左到右为小安、小白、小晨；小白在小安右边，在小晨左边。</p><p><strong>易错：</strong> 不能省略观察方向后随意判断左右。</p><p><a href="/life/math/primary/grade-1/formulas#p1-11">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-11">练习题组</a></p><h2 id="p1-12" tabindex="-1">认识平面图形与拼组 <a class="header-anchor" href="#p1-12" aria-label="Permalink to &quot;认识平面图形与拼组 {#p1-12}&quot;">​</a></h2><p><strong>定义与条件：</strong> 三角形有 3 条直边；长方形和正方形都有 4 条直边和 4 个直角，正方形四边同样长；圆的边界是一条闭合曲线。</p><p><strong>方法：</strong> 先看边是直的还是曲的，再数边；转动图形不会改变它的类别。拼图时注意只计算最外边界。</p><p><strong>例子：</strong> 两块一样大的正方形沿整条边拼接，可以组成一个长方形；内部接缝不属于外边界。</p><p><strong>易错：</strong> 斜放的正方形仍是正方形，不能仅凭“摆得正不正”判断。</p>',76)),n("p",null,[i(e,{src:"/life/math/diagrams/geometry-area.svg",alt:"长方形与三角形的本地形状示意"})]),r[1]||(r[1]=a('<p>图中标注底 4、高 3。这里先观察长方形的四边与三角形的三边；面积计算在后续年级学习，图不是本节习题的附加已知条件。</p><p><a href="/life/math/primary/grade-1/formulas#p1-12">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-12">练习题组</a></p><h2 id="p1-13" tabindex="-1">认识立体图形与表面 <a class="header-anchor" href="#p1-13" aria-label="Permalink to &quot;认识立体图形与表面 {#p1-13}&quot;">​</a></h2><p><strong>定义与条件：</strong> 长方体、正方体、圆柱和球是立体图形；长方形、圆等是平面图形。正方体有六个大小相同的正方形面。</p><p><strong>方法：</strong> 观察“能否平放、能否滚动、有哪些表面”，但最终以形状特征判断，不能只凭一种动作。</p><p><strong>例子：</strong> 圆柱有两个同样大的圆形底面和一个曲面；球表面弯曲，各方向都能滚动。</p><p><strong>易错：</strong> 圆柱的底面是圆，圆柱本身不是圆。</p><p><a href="/life/math/primary/grade-1/formulas#p1-13">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-13">练习题组</a></p><h2 id="p1-14" tabindex="-1">长度比较与厘米测量 <a class="header-anchor" href="#p1-14" aria-label="Permalink to &quot;长度比较与厘米测量 {#p1-14}&quot;">​</a></h2><p><strong>定义与条件：</strong> 比较长度要统一起点和方向；厘米是常用长度单位。尺上相邻厘米刻度之间的距离为 1 厘米。</p><p><strong>方法：</strong> 测量时让物体一端对准 0 刻度，读另一端；若起点不是 0，终点读数减起点读数才是长度。</p><p><strong>例子：</strong> 铅笔一端对准 2 厘米，另一端对准 9 厘米，长度是 9−2＝7 厘米。</p><p><strong>易错：</strong> 尺的边缘不一定是 0 刻度；不能直接把终点数字当作长度。</p><p><a href="/life/math/primary/grade-1/formulas#p1-14">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-14">练习题组</a></p><h2 id="p1-15" tabindex="-1">整时、半时与先后 <a class="header-anchor" href="#p1-15" aria-label="Permalink to &quot;整时、半时与先后 {#p1-15}&quot;">​</a></h2><p><strong>定义与条件：</strong> 钟面长针通常是分针，短针是时针。分针指 12 时为整时；分针指 6、时针在两个数字之间时为半时。</p><p><strong>方法：</strong> 先看分针，再看时针已经经过哪个数字；“几时半”的时针已经越过几，却还未到下一个数字。</p><p><strong>例子：</strong> 分针指 6，时针在 3 与 4 之间，表示 3 时 30 分，也叫 3 时半。</p><p><strong>易错：</strong> 时针还没到 4，就不能读成 4 时半。</p><p><a href="/life/math/primary/grade-1/formulas#p1-15">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-15">练习题组</a></p><h2 id="p1-16" tabindex="-1">人民币元、角、分 <a class="header-anchor" href="#p1-16" aria-label="Permalink to &quot;人民币元、角、分 {#p1-16}&quot;">​</a></h2><p><strong>定义与条件：</strong> 元、角、分是人民币金额单位，购买时应先统一单位，再比较或相加减。面额不同的钱可等值兑换。</p><p><strong>方法：</strong> 先把金额换成同一单位，付款减去价格得到找回的钱；最后按需要换回元和角。</p><p><strong>例子：</strong> 1 元 5 角是 15 角；买 7 角的铅笔，应找回 15−7＝8 角。</p><p><strong>易错：</strong> 1 元不是 1 角；相同数字带不同单位的金额不同。</p><p><a href="/life/math/primary/grade-1/formulas#p1-16">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-16">练习题组</a></p><h2 id="p1-17" tabindex="-1">分类、计数与简单统计 <a class="header-anchor" href="#p1-17" aria-label="Permalink to &quot;分类、计数与简单统计 {#p1-17}&quot;">​</a></h2><p><strong>定义与条件：</strong> 分类依据是用来分组的共同特征，例如颜色、形状或用途。按同一标准分类时，每个对象应归入适当的一组。</p><p><strong>方法：</strong> 先明确标准，逐个做标记避免遗漏，最后检查各组数量之和等于总数。简单统计表可记录组名与数量。</p><p><strong>例子：</strong> 6 个球中红球 2 个、蓝球 4 个，按颜色分两组；两组数量相加 2＋4＝6。</p><p><strong>易错：</strong> 不能在一次按颜色分类中，把“红色”和“圆形”并列为互斥类别。</p><p><a href="/life/math/primary/grade-1/formulas#p1-17">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-17">练习题组</a></p><h2 id="p1-18" tabindex="-1">重复规律与数列初步 <a class="header-anchor" href="#p1-18" aria-label="Permalink to &quot;重复规律与数列初步 {#p1-18}&quot;">​</a></h2><p><strong>定义与条件：</strong> 重复规律由一个按固定顺序循环出现的单元构成；数的规律还可能表现为每次增加或减少相同的数。</p><p><strong>方法：</strong> 先找最小重复单元或相邻数的变化，再用后面的项检验；有限几个数可能有不同规律，须按题目给出的规则作答。</p><p><strong>例子：</strong> 红、蓝、红、蓝……的重复单元是“红、蓝”；2、4、6、8 按每次加 2 的规则继续是 10。</p><p><strong>易错：</strong> 不能只观察前两个位置就忽略题目明确的规则。</p><p><a href="/life/math/primary/grade-1/formulas#p1-18">对应公式</a> · <a href="/life/math/primary/grade-1/exercises#p1-18">练习题组</a></p>',38))])}const y=p(g,[["render",l]]);export{x as __pageData,y as default};
